                        hub.activateClassicWorldMonsterArmorBreak(4,-1,monster.objectId(),1,1);check(hub.strikerGaleClassicWorldMonster(4,-1,monster.objectId(),System.nanoTime(),60),"WORLD NPC Striker installed");String npcKey=CombatClassDamage.key(caster.battleCharacterType(),false);rf.set(null,ClassDamageRegression.with(baseline,Map.of(npcKey,1.25,"STRIKER_DMG2",1.2)));npc=monsterHit(caster,hub,monster,capture);actual=npc.actual();want=(int)(npc.base()*1.25);if(ranged)want=(int)(want*1.2);check(actual==want,"WORLD NPC Striker after class weapon="+type+" expected="+want+" actual="+actual);population.strikerGale(4,monster.objectId(),1,1);
